// ===== COMMENT SCRAPER =====
// Scrapes comments from recent posts and competitors

const staticData = $getWorkflowStaticData('global');
const posts = staticData.posts || [];
const niche = staticData.niche || 'general';
const kb = staticData.knowledgeBase || {};

// Get recent posts to check comments on
const recentPosts = posts.slice(-10);

// Competitor accounts to monitor
const competitors = kb.competitors || [];

const commentTasks = [];

// Check comments on our posts
for (const post of recentPosts) {
  commentTasks.push({
    type: 'own_post',
    postId: post.id,
    postHook: post.hook,
    url: `https://www.instagram.com/p/${post.id}/`,
    tasks: [
      'Scrape all comments',
      'Identify questions asked',
      'Find pain points mentioned',
      'Note emotional language used',
      'Find product/service requests',
      'Identify potential leads (asking for more info)'
    ]
  });
}

// Check comments on competitor posts
for (const competitor of competitors.slice(0, 5)) {
  commentTasks.push({
    type: 'competitor',
    competitor: competitor.name || competitor,
    url: competitor.profileUrl || `https://www.instagram.com/${competitor}/`,
    tasks: [
      'Scrape comments from top posts',
      'Find audience pain points',
      'Note questions people ask',
      'Identify what content gets most engagement',
      'Find gaps in competitor responses'
    ]
  });
}

return [{
  json: {
    commentTasks,
    chatId: staticData.chatId
  }
}];

// ===== COMMENT ANALYSIS ENGINE =====
// Analyzes scraped comments for insights

const input = $input.first().json;
const staticData = $getWorkflowStaticData('global');
const kb = staticData.knowledgeBase || {};

// Initialize comment insights
if (!staticData.commentInsights) {
  staticData.commentInsights = {
    questions: [],
    painPoints: [],
    emotionalTriggers: [],
    productRequests: [],
    leads: [],
    sentiment: {},
    commonWords: {},
    engagementPatterns: []
  };
}

const insights = staticData.commentInsights;

// Process each comment batch
for (const task of input.commentData || []) {
  const comments = task.comments || [];

  for (const comment of comments) {
    const text = comment.text?.toLowerCase() || '';

    // Extract questions
    if (text.includes('?') || text.startsWith('how') || text.startsWith('what') || text.startsWith('why') || text.startsWith('when') || text.startsWith('where')) {
      insights.questions.push({
        question: comment.text,
        source: task.type,
        postId: task.postId,
        timestamp: new Date().toISOString()
      });
    }

    // Extract pain points
    const painKeywords = ['struggle', 'hard', 'difficult', 'can\'t', 'don\'t know', 'help', 'frustrated', 'confused', 'stuck', 'fail', 'problem'];
    if (painKeywords.some(kw => text.includes(kw))) {
      insights.painPoints.push({
        point: comment.text,
        source: task.type,
        timestamp: new Date().toISOString()
      });
    }

    // Extract emotional triggers
    const emotionKeywords = ['love', 'hate', 'amazing', 'terrible', 'best', 'worst', 'changed my life', 'game changer', 'waste', 'scam', 'incredible'];
    for (const kw of emotionKeywords) {
      if (text.includes(kw)) {
        insights.emotionalTriggers.push({
          trigger: kw,
          context: comment.text,
          sentiment: ['love', 'amazing', 'best', 'changed my life', 'game changer', 'incredible'].includes(kw) ? 'positive' : 'negative'
        });
      }
    }

    // Extract product requests
    const productKeywords = ['where can i buy', 'do you sell', 'product', 'link', 'where to get', 'how much', 'price', 'cost', 'purchase', 'order'];
    if (productKeywords.some(kw => text.includes(kw))) {
      insights.productRequests.push({
        request: comment.text,
        source: task.type,
        postId: task.postId,
        timestamp: new Date().toISOString()
      });
    }

    // Extract leads (people wanting more info)
    const leadKeywords = ['interested', 'want to know more', 'tell me more', 'dm me', 'send me', 'need this', 'want this', 'sign me up'];
    if (leadKeywords.some(kw => text.includes(kw))) {
      insights.leads.push({
        comment: comment.text,
        username: comment.username,
        source: task.type,
        postId: task.postId,
        timestamp: new Date().toISOString()
      });
    }

    // Word frequency analysis
    const words = text.split(/\s+/).filter(w => w.length > 3);
    for (const word of words) {
      insights.commonWords[word] = (insights.commonWords[word] || 0) + 1;
    }
  }
}

// Sort common words
const topWords = Object.entries(insights.commonWords)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 50)
  .map(([word, count]) => `${word} (${count})`);

// Update knowledge base with comment insights
if (!kb.audienceLanguage) kb.audienceLanguage = [];
kb.audienceLanguage = [...new Set([...kb.audienceLanguage, ...topWords])];

if (!kb.questions) kb.questions = [];
kb.questions = [...new Set([...kb.questions, ...insights.questions.map(q => q.question)])];

if (!kb.painPoints) kb.painPoints = [];
kb.painPoints = [...new Set([...kb.painPoints, ...insights.painPoints.map(p => p.point)])];

staticData.commentInsights = insights;
staticData.knowledgeBase = kb;

return [{
  json: {
    insights,
    topWords,
    chatId: input.chatId,
    newQuestions: insights.questions.length,
    newPainPoints: insights.painPoints.length,
    newLeads: insights.leads.length,
    productRequests: insights.productRequests.length
  }
}];

// ===== AUTO-REPLY TO COMMENTS =====
// Generates smart replies to engage commenters

const input = $input.first().json;
const { insights, chatId } = input;

// Generate reply templates
const replyTemplates = {
  question: [
    'Great question! 💡 [Answer based on knowledge base]',
    'I was wondering the same thing! Here\'s what I found...',
    'Thanks for asking! The answer is...',
  ],
  painPoint: [
    'I totally understand that struggle! 💪 Here\'s what helped me...',
    'You\'re not alone in this! The key is...',
    'I\'ve been there too. What worked for me was...',
  ],
  positive: [
    'Thank you so much! 🙏 Glad it helped!',
    'Really appreciate that! ❤️',
    'That means a lot! More content like this coming soon! 🔥',
  ],
  lead: [
    'Thanks for your interest! 💬 Check the link in my bio!',
    'So glad you asked! DM me for more details! 📩',n    'I\'d love to help! Send me a DM! 🚀',
  ]
};

// Auto-like comments (boost engagement)
const autoLike = insights.leads.map(lead => ({
  action: 'like',
  commentId: lead.commentId,
  username: lead.username
}));

// Auto-reply to questions
const autoReplies = insights.questions.slice(0, 10).map(q => ({
  action: 'reply',
  commentId: q.commentId,
  reply: replyTemplates.question[Math.floor(Math.random() * replyTemplates.question.length)],
  originalQuestion: q.question
}));

return [{
  json: {
    chatId,
    autoLike,
    autoReplies,
    totalEngagements: autoLike.length + autoReplies.length
  }
}];

